164	\begin{definition}[Low-degree polynomial measurements]\label{def:ld-meas}
165		\lean{MIPStarRE.QPBT.PolyIndex, MIPStarRE.QPBT.PolyMeas, MIPStarRE.QPBT.PolyMeasFamily, MIPStarRE.QPBT.PolyMeasTuple}
